    /**
     * Returns up to [count] questions, optionally filtered by a free-text [topic]
     * (matched against anime / theme / text) and biased toward the chosen
     * [difficulty] tier. The selected tier is served first (shuffled) and the
     * remainder is filled from other tiers, so harder difficulties actually
     * surface harder questions instead of only getting a shorter timer.
     */
    fun getQuestions(count: Int, topic: String = "", difficulty: String = "Medium"): List<Question> {
        val base = if (topic.isBlank()) {
            allQuestions
        } else {
            val filtered = allQuestions.filter { it.matches(topic) }
            if (filtered.isEmpty()) allQuestions else filtered
        }
        val exact = base.filter { it.difficulty.equals(difficulty, ignoreCase = true) }.shuffled()
        val rest = base.filter { !it.difficulty.equals(difficulty, ignoreCase = true) }.shuffled()
        return (exact + rest).distinctBy { it.text }.map { it.withShuffledOptions() }.take(count)
    }

    /**
     * Distinct, alphabetically sorted autocomplete keywords drawn from the bank:
     * series names ("One Piece", "Naruto"…) plus theme tags ("Characters",
     * "Powers", "Story"…). Used to power the topic-field suggestions.
     */
    fun suggestions(): List<String> =
        (allQuestions.map { it.anime } + allQuestions.map { it.theme })
            .distinct()
            .sorted()

    private fun Question.matches(topic: String): Boolean {
        val t = topic.trim()
        if (t.isEmpty()) return true
        return anime.contains(t, ignoreCase = true) ||
            theme.contains(t, ignoreCase = true) ||
            text.contains(t, ignoreCase = true)
    }
}
